import { useState, type ReactNode } from 'react';
import { cn } from '@/lib/utils';
import type { FestEvent } from '@/types/event';

interface EventArtProps {
  event: FestEvent;
  className?: string;
  /** Rendered only over the placeholder — real event art already carries its own title/frame. */
  placeholderOverlay?: ReactNode;
}

/**
 * Event art from the JSON `image` field (Claude.md §7). AVIF with a WebP fallback, both
 * generated by `npm run images:events`. Until an event's art exists the <img> 404s and we
 * swap to the placeholder: corner brackets are the Design.md §Shapes "signature ornament".
 */
export function EventArt({ event, className, placeholderOverlay }: EventArtProps) {
  const [failed, setFailed] = useState(!event.image);

  if (!failed) {
    return (
      <picture className={cn('relative block overflow-hidden bg-charcoal', className)}>
        <source srcSet={event.image} type="image/avif" />
        <img
          src={event.image.replace(/\.avif$/, '.webp')}
          alt=""
          loading="lazy"
          decoding="async"
          draggable={false}
          onError={() => setFailed(true)}
          className="h-full w-full select-none object-cover object-center"
        />
      </picture>
    );
  }

  const bgClass = event.category === 'management' ? 'bg-gradient-to-br from-charcoal to-ink' : 'bg-gradient-to-br from-ink to-deep-blue';

  return (
    <div className={cn('relative flex items-center justify-center overflow-hidden', bgClass, className)}>
      <span
        aria-hidden="true"
        className="font-display text-5xl text-accent/30"
      >
        {event.name.replace(/^The\s+/i, '').charAt(0)}
      </span>
      {/* corner brackets */}
      <span aria-hidden="true" className="absolute left-2 top-2 h-3 w-3 border-l border-t border-accent/50" />
      <span aria-hidden="true" className="absolute right-2 top-2 h-3 w-3 border-r border-t border-accent/50" />
      <span aria-hidden="true" className="absolute bottom-2 left-2 h-3 w-3 border-b border-l border-accent/50" />
      <span aria-hidden="true" className="absolute bottom-2 right-2 h-3 w-3 border-b border-r border-accent/50" />
      {placeholderOverlay}
    </div>
  );
}
